/* Shared commercial calculations. All profit/cost amounts are net of recoverable VAT.
   Order reports are not settlement reports: caller must label estimated inputs. */
(function(root){
 'use strict';
 const valid=(...values)=>values.every(Number.isFinite);
 function result(revenue,goods,shipping,fees=0,credit=0,other=0){
  if(!valid(revenue,goods,shipping,fees,credit,other))return null;
  const cost=goods+shipping+fees+other-credit,profit=revenue-cost;
  return {revenue,goods,shipping,fees,credit,other,cost,profit,markup:cost>0?profit/cost:null,margin:revenue>0?profit/revenue:null};
 }
 function amazonFees(ttc,rate,surcharge){
  if(!valid(ttc,rate,surcharge)||ttc<0||rate<0||surcharge<0)return null;
  const commission=ttc*rate,extra=commission*surcharge;
  return {commission,surcharge:extra,total:commission+extra};
 }
 function amazonAtPrice(ttc,costHt,vat,rate,surcharge,tax=null){
  const fees=amazonFees(ttc,rate,surcharge);
  if(!fees||!valid(costHt,vat)||costHt<0||vat<0||(tax!==null&&(!Number.isFinite(tax)||tax<0||tax>ttc)))return null;
  const revenue=tax===null?ttc/(1+vat):ttc-tax;
