 }
 function amazonTarget(costHt,vat,rate,surcharge,markup){
  if(!valid(costHt,vat,rate,surcharge,markup)||costHt<0||vat<0||rate<0||surcharge<0||markup<0)return null;
  const denominator=1/(1+vat)-rate*(1+surcharge)*(1+markup);
  return denominator>0?costHt*(1+markup)/denominator:null;
 }
 function temuAtPrice(localHt,goods,shipping,vat,country,customerTtc=null){
  if(!country||!valid(localHt,goods,shipping,vat,country.fx,country.k,country.t)||country.fx<=0||localHt<0||vat<0||goods<0||shipping<0||country.k<0||country.t<0)return null;
  const thresholdBasis=customerTtc===null?localHt*(1+vat):customerTtc;
  if(!Number.isFinite(thresholdBasis))return null;
