  const cost=goods+shipping,credit=country.k/country.fx/(1+vat);
  let euro=ceil(Math.max(0,cost-credit)*(1+markup))+supplement,local=ceil(euro*country.fx);
  if(local*(1+vat)>=country.t){euro=ceil(cost*(1+markup))+supplement;local=ceil(euro*country.fx);}
  return {...temuAtPrice(local,goods,shipping,vat,country),local,finalEUR:local/country.fx,price20:local/country.fx-supplement};
 }
